# Brazilian ABNT2 — what is engraved on the keys, as Windows and Linux type it.
# Format: see userspace/lib/keymap/keymap.cst. Scancodes are PS/2 Set 1.
name Português (Brasil, ABNT2)

0x29 ' "
0x02 1 ! ¹
0x03 2 @ ²
0x04 3 # ³
0x05 4 $ £
0x06 5 % ¢
0x07 6 dead:¨ ¬
0x08 7 &
0x09 8 *
0x0A 9 (
0x0B 0 )
0x0C - _
0x0D = + §

0x10 q Q /
0x11 w W ?
0x12 e E ° €
0x13 r R
0x14 t T
0x15 y Y
0x16 u U
0x17 i I
0x18 o O
0x19 p P
0x1A dead:´ dead:`
0x1B [ { ª

0x1E a A
0x1F s S
0x20 d D
0x21 f F
0x22 g G
0x23 h H
0x24 j J
0x25 k K
0x26 l L
0x27 ç Ç
0x28 dead:~ dead:^
0x2B ] } º

0x56 \ |
0x2C z Z
0x2D x X
0x2E c C ₢
0x2F v V
0x30 b B
0x31 n N
0x32 m M
0x33 , <
0x34 . >
0x35 ; :
0x73 / ? °

# The keypad's decimal key types a comma; the extra key beside it, a point.
0x53 ,
0x7E .

# ´ then c: ç, as Brazilian systems do (Unicode would make it ć).
compose dead:´ c ç
compose dead:´ C Ç
